//! `Microsoft.Authorization`: role definitions and role assignments at any scope,
//! and, when enabled, enforcement of them on Resource Manager requests.
//!
//! The built-in roles are Azure's own, with their real ids and permissions
//! (`builtin-roles.json`, regenerated by `tools/builtin-roles/generate.py`).

use std::collections::BTreeMap;
use std::sync::OnceLock;

use axum::response::{IntoResponse, Response};
use http::{Method, StatusCode};
use serde_json::{json, Value};

use super::{ArmRequest, ArmState};
use crate::http_util::json_response;
use crate::{ArmError, Engine};

const ASSIGNMENTS: &str = "Microsoft.Authorization/roleAssignments";
const DEFINITIONS: &str = "Microsoft.Authorization/roleDefinitions";

/// Azure's built-in role definitions: `name` (the role's GUID), `roleName`,
/// `description` and `permissions`.
fn builtin_roles() -> &'static [Value] {
    static ROLES: OnceLock<Vec<Value>> = OnceLock::new();
    ROLES.get_or_init(|| serde_json::from_str(include_str!("builtin-roles.json")).expect("built-in roles are valid JSON"))
}

#[derive(Clone)]
struct Assignment {
    id: String,
    name: String,
    scope: String,
    role: String,
    principal_id: String,
    principal_type: Option<String>,
    description: Option<Value>,
    condition: Option<Value>,
    condition_version: Option<Value>,
    delegated_identity: Option<Value>,
    created_on: String,
    updated_on: String,
    created_by: Option<String>,
}

#[derive(Clone)]
struct CustomRole {
    name: String,
    role_name: String,
    description: Value,
    permissions: Value,
    assignable_scopes: Vec<String>,
    created_on: String,
    updated_on: String,
    created_by: Option<String>,
}

/// Role assignments and custom role definitions.
#[derive(Default)]
pub struct AuthorizationState {
    /// Keyed by lowercased assignment id.
    assignments: BTreeMap<String, Assignment>,
    /// Keyed by lowercased role GUID.
    custom: BTreeMap<String, CustomRole>,
}

fn now() -> String {
    chrono::Utc::now().format("%Y-%m-%dT%H:%M:%S%.6fZ").to_string()
}

fn is_guid(text: &str) -> bool {
    uuid::Uuid::parse_str(text).is_ok() && text.len() == 36
}

/// Whether `ancestor` is `scope` or contains it. `/` contains every scope.
fn covers(ancestor: &str, scope: &str) -> bool {
    let ancestor = ancestor.trim_end_matches('/').to_ascii_lowercase();
    let scope = scope.trim_end_matches('/').to_ascii_lowercase();
    ancestor.is_empty() || scope == ancestor || scope.starts_with(&format!("{ancestor}/"))
}

/// Whether an action pattern (`Microsoft.Storage/*/read`, `*`) matches an action.
fn action_matches(pattern: &str, action: &str) -> bool {
    let pattern = pattern.to_ascii_lowercase();
    let action = action.to_ascii_lowercase();
    let parts: Vec<&str> = pattern.split('*').collect();
    if parts.len() == 1 {
        return pattern == action;
    }
    let mut rest = action.as_str();
    for (index, part) in parts.iter().enumerate() {
        if index == 0 {
            match rest.strip_prefix(part) {
                Some(after) => rest = after,
                None => return false,
            }
        } else if index == parts.len() - 1 {
            return rest.ends_with(part);
        } else {
            match rest.find(part) {
                Some(at) => rest = &rest[at + part.len()..],
                None => return false,
            }
        }
    }
    true
}

/// Whether a role's permissions allow a control-plane action.
fn permits(permissions: &Value, action: &str) -> bool {
    permissions.as_array().into_iter().flatten().any(|block| {
        let list = |key: &str| block.get(key).and_then(Value::as_array).cloned().unwrap_or_default();
        let matches = |key: &str| list(key).iter().filter_map(Value::as_str).any(|p| action_matches(p, action));
        matches("actions") && !matches("notActions")
    })
}

fn role_guid(role_definition_id: &str) -> &str {
    role_definition_id.trim_end_matches('/').rsplit('/').next().unwrap_or("")
}

/// The prefix role definition ids carry when read at `scope`.
fn definition_prefix(scope: &str) -> String {
    let segments: Vec<&str> = scope.split('/').filter(|s| !s.is_empty()).collect();
    match segments.as_slice() {
        [first, subscription, ..] if first.eq_ignore_ascii_case("subscriptions") => format!("/subscriptions/{subscription}"),
        _ => String::new(),
    }
}

fn builtin_json(role: &Value, prefix: &str) -> Value {
    let name = role["name"].as_str().unwrap_or_default();
    json!({
        "id": format!("{prefix}/providers/{DEFINITIONS}/{name}"),
        "name": name,
        "type": DEFINITIONS,
        "properties": {
            "roleName": role["roleName"],
            "type": "BuiltInRole",
            "description": role["description"],
            "assignableScopes": ["/"],
            "permissions": role["permissions"],
        },
    })
}

impl CustomRole {
    fn to_json(&self, prefix: &str) -> Value {
        json!({
            "id": format!("{prefix}/providers/{DEFINITIONS}/{}", self.name),
            "name": self.name,
            "type": DEFINITIONS,
            "properties": {
                "roleName": self.role_name,
                "type": "CustomRole",
                "description": self.description,
                "assignableScopes": self.assignable_scopes,
                "permissions": self.permissions,
                "createdOn": self.created_on,
                "updatedOn": self.updated_on,
                "createdBy": self.created_by,
                "updatedBy": self.created_by,
            },
        })
    }
}

impl Assignment {
    fn to_json(&self, subscription: &str) -> Value {
        let mut properties = json!({
            "roleDefinitionId": format!("/subscriptions/{subscription}/providers/{DEFINITIONS}/{}", self.role),
            "principalId": self.principal_id,
            "scope": self.scope,
            "createdOn": self.created_on,
            "updatedOn": self.updated_on,
            "createdBy": self.created_by,
            "updatedBy": self.created_by,
        });
        for (key, value) in [
            ("principalType", self.principal_type.clone().map(Value::String)),
            ("description", self.description.clone()),
            ("condition", self.condition.clone()),
            ("conditionVersion", self.condition_version.clone()),
            ("delegatedManagedIdentityResourceId", self.delegated_identity.clone()),
        ] {
            if let Some(value) = value {
                properties[key] = value;
            }
        }
        json!({"id": self.id, "name": self.name, "type": ASSIGNMENTS, "properties": properties})
    }
}

/// The parts of a `$filter` the role APIs accept.
#[derive(Default)]
struct Filter {
    at_scope: bool,
    principal: Option<String>,
    role_name: Option<String>,
    role_type: Option<String>,
}

fn parse_filter(filter: Option<&str>) -> Result<Filter, ArmError> {
    let mut out = Filter::default();
    let Some(filter) = filter.filter(|f| !f.trim().is_empty()) else {
        return Ok(out);
    };
    for clause in filter.split(" and ") {
        let clause = clause.trim();
        let quoted = |text: &str| text.trim().trim_matches('\'').to_string();
        let lower = clause.to_ascii_lowercase();
        if lower == "atscope()" {
            out.at_scope = true;
        } else if let Some(rest) = lower.strip_prefix("principalid eq ") {
            out.principal = Some(quoted(&clause[clause.len() - rest.len()..]));
        } else if lower.starts_with("assignedto(") && lower.ends_with(')') {
            out.principal = Some(quoted(&clause["assignedTo(".len()..clause.len() - 1]));
        } else if let Some(rest) = lower.strip_prefix("rolename eq ") {
            out.role_name = Some(quoted(&clause[clause.len() - rest.len()..]));
        } else if let Some(rest) = lower.strip_prefix("type eq ") {
            out.role_type = Some(quoted(&clause[clause.len() - rest.len()..]));
        } else {
            return Err(ArmError::bad_request(
                "UnsupportedQuery",
                format!("The filter '{filter}' is not supported. Supported filters are atScope(), principalId eq '{{id}}', assignedTo('{{id}}'), roleName eq '{{name}}' and type eq '{{type}}'."),
            ));
        }
    }
    Ok(out)
}

/// Forgets the role assignments at or under a deleted scope.
pub fn forget_scope(engine: &Engine, scope: &str) {
    engine.state::<AuthorizationState>().lock().assignments.retain(|_, a| !covers(scope, &a.scope));
}

/// What a request needs permission for: the action and the scope it acts on.
/// `None` for requests outside a subscription (tenant-level reads, metadata),
/// which every signed-in caller may make.
pub fn required_permission(method: &Method, segments: &[String]) -> Option<(String, String)> {
    let lower: Vec<String> = segments.iter().map(|s| s.to_ascii_lowercase()).collect();
    let lower: Vec<&str> = lower.iter().map(String::as_str).collect();
    let verb = |method: &Method| match method.as_str() {
        "GET" | "HEAD" => "read",
        "PUT" | "PATCH" => "write",
        "DELETE" => "delete",
        _ => "action",
    };
    let ["subscriptions", _, rest @ ..] = lower.as_slice() else {
        return None;
    };
    let subscription = format!("/subscriptions/{}", segments[1]);
    let group_id = || format!("{subscription}/resourceGroups/{}", segments[3]);
    let simple = |action: &str, scope: String| Some((action.to_string(), scope));
    match rest {
        [] => simple("Microsoft.Resources/subscriptions/read", subscription),
        ["resourcegroups"] => simple("Microsoft.Resources/subscriptions/resourceGroups/read", subscription),
        ["resourcegroups", _] => {
            Some((format!("Microsoft.Resources/subscriptions/resourceGroups/{}", verb(method)), group_id()))
        }
        ["resourcegroups", _, "resources"] => simple("Microsoft.Resources/subscriptions/resourceGroups/resources/read", group_id()),
        ["resources"] => simple("Microsoft.Resources/subscriptions/resources/read", subscription),
        ["providers"] | ["providers", _] | ["operationresults", ..] => None,
        ["resourcegroups", _, "providers", _, tail @ ..] if !tail.is_empty() => {
            provider_permission(method, &group_id(), &segments[5], &segments[6..])
        }
        ["resourcegroups", _, "deployments", ..] => {
            let mut path = vec!["deployments".to_string()];
            path.extend_from_slice(&segments[5..]);
            provider_permission(method, &group_id(), "Microsoft.Resources", &path)
        }
        ["providers", _, tail @ ..] if !tail.is_empty() => provider_permission(method, &subscription, &segments[3], &segments[4..]),
        ["deployments", ..] => provider_permission(method, &subscription, "Microsoft.Resources", &segments[2..]),
        _ => None,
    }
}

/// The permission for `{base}/providers/{namespace}/{rest...}`.
fn provider_permission(method: &Method, base: &str, namespace: &str, rest: &[String]) -> Option<(String, String)> {
    // An extension resource: `{resource}/providers/{namespace}/{type}/...`.
    if let Some(at) = rest.iter().position(|s| s.eq_ignore_ascii_case("providers")) {
        if at % 2 == 0 && at + 1 < rest.len() {
            let inner = format!("{base}/providers/{namespace}/{}", rest[..at].join("/"));
            return provider_permission(method, &inner, &rest[at + 1], &rest[at + 2..]);
        }
    }
    let odd = rest.len() % 2 == 1;
    let (path, action) = match (method.as_str(), odd) {
        ("POST", true) => (&rest[..rest.len() - 1], Some(rest[rest.len() - 1].as_str())),
        _ => (rest, None),
    };
    let types: Vec<&str> = path.iter().step_by(2).map(String::as_str).collect();
    let mut kind = namespace.to_string();
    for t in &types {
        kind.push('/');
        kind.push_str(t);
    }
    // A collection is read at its parent's scope.
    let scope_path = if path.len() % 2 == 1 { &path[..path.len() - 1] } else { path };
    let scope = if scope_path.is_empty() {
        base.to_string()
    } else {
        format!("{base}/providers/{namespace}/{}", scope_path.join("/"))
    };
    let action = match action {
        Some(action) => format!("{kind}/{action}/action"),
        None => format!(
            "{kind}/{}",
            match method.as_str() {
                "GET" | "HEAD" => "read",
                "PUT" | "PATCH" => "write",
                "DELETE" => "delete",
                _ => "action",
            }
        ),
    };
    Some((action, scope))
}

impl ArmRequest<'_> {
    /// The ids a caller's role assignments may name: the token's object id, and
    /// for a managed identity's token (whose object id is its client id) the
    /// identity's principal id.
    fn principal_ids(&self, oid: &str) -> Vec<String> {
        let mut ids = vec![oid.to_string()];
        let state = self.engine.state::<ArmState>();
        let state = state.lock();
        for resource in state.resources() {
            if resource.resource_type.eq_ignore_ascii_case("Microsoft.ManagedIdentity/userAssignedIdentities")
                && resource.properties.get("clientId").and_then(Value::as_str) == Some(oid)
            {
                if let Some(principal) = resource.properties.get("principalId").and_then(Value::as_str) {
                    ids.push(principal.to_string());
                }
            }
        }
        for (principal, client) in &state.system_identity_clients {
            if client == oid {
                ids.push(principal.clone());
            }
        }
        ids
    }

    /// Refuses the request unless the caller holds a role that permits it.
    pub(super) fn check_access(&self, segments: &[String]) -> Result<(), ArmError> {
        let config = self.engine.config();
        let Some(oid) = self.principal else {
            return Ok(());
        };
        if !config.enforce_rbac || oid == crate::auth::PROVISIONING_CLIENT || config.rbac_owners.iter().any(|o| o == oid) {
            return Ok(());
        }
        let Some((action, scope)) = required_permission(self.method, segments) else {
            return Ok(());
        };
        let ids = self.principal_ids(oid);
        let state = self.engine.state::<AuthorizationState>();
        let state = state.lock();
        let allowed = state
            .assignments
            .values()
            .filter(|a| ids.iter().any(|id| id.eq_ignore_ascii_case(&a.principal_id)) && covers(&a.scope, &scope))
            .any(|a| {
                let builtin = builtin_roles().iter().find(|r| r["name"].as_str().is_some_and(|n| n.eq_ignore_ascii_case(&a.role)));
                match builtin {
                    Some(role) => permits(&role["permissions"], &action),
                    None => state.custom.get(&a.role.to_ascii_lowercase()).is_some_and(|r| permits(&r.permissions, &action)),
                }
            });
        if allowed {
            return Ok(());
        }
        Err(ArmError::new(
            StatusCode::FORBIDDEN,
            "AuthorizationFailed",
            format!(
                "The client '{oid}' with object id '{oid}' does not have authorization to perform action '{action}' over scope '{scope}' or the scope is invalid. If access was recently granted, please refresh your credentials."
            ),
        ))
    }

    /// A request under `{scope}/providers/Microsoft.Authorization/{kind}`.
    pub(super) fn authorization(&self, scope: &str, kind: &str, rest: &[String]) -> Result<Response, ArmError> {
        self.require_scope(scope)?;
        let filter = self.filter.as_deref();
        match (kind, self.method.as_str(), rest) {
            ("roleassignments", "GET", []) => self.list_assignments(scope, filter),
            ("roleassignments", _, [name]) => self.assignment(scope, name),
            ("roledefinitions", "GET", []) => self.list_definitions(scope, filter),
            ("roledefinitions", _, [name]) => self.definition(scope, name),
            _ => Err(self.unsupported(rest)),
        }
    }

    /// Checks that a scope names something that exists.
    fn require_scope(&self, scope: &str) -> Result<(), ArmError> {
        let segments: Vec<&str> = scope.split('/').filter(|s| !s.is_empty()).collect();
        let config = self.engine.config();
        match segments.as_slice() {
            [] => Ok(()),
            ["subscriptions", subscription, rest @ ..] => {
                if !subscription.eq_ignore_ascii_case(&config.subscription_id) {
                    return Err(ArmError::not_found(
                        "SubscriptionNotFound",
                        format!("The subscription '{subscription}' could not be found."),
                    ));
                }
                match rest {
                    [] => Ok(()),
                    [group_word, group] if group_word.eq_ignore_ascii_case("resourceGroups") => self.require_group(group).map(|_| ()),
                    [group_word, group, ..] if group_word.eq_ignore_ascii_case("resourceGroups") => {
                        self.require_group(group)?;
                        let exists = self.engine.state::<ArmState>().lock().resource(scope).is_some();
                        if exists {
                            Ok(())
                        } else {
                            Err(ArmError::not_found("ResourceNotFound", format!("The resource '{scope}' was not found.")))
                        }
                    }
                    _ => Err(invalid_scope(scope)),
                }
            }
            _ => Err(invalid_scope(scope)),
        }
    }

    fn list_assignments(&self, scope: &str, filter: Option<&str>) -> Result<Response, ArmError> {
        let filter = parse_filter(filter)?;
        let subscription = &self.engine.config().subscription_id;
        let state = self.engine.state::<AuthorizationState>();
        let state = state.lock();
        let items: Vec<Value> = state
            .assignments
            .values()
            // Assignments that apply at the scope, and (without atScope()) those below it.
            .filter(|a| covers(&a.scope, scope) || (!filter.at_scope && covers(scope, &a.scope)))
            .filter(|a| filter.principal.as_deref().is_none_or(|p| p.eq_ignore_ascii_case(&a.principal_id)))
            .map(|a| a.to_json(subscription))
            .collect();
        Ok(json_response(StatusCode::OK, &json!({"value": items})))
    }

    fn assignment(&self, scope: &str, name: &str) -> Result<Response, ArmError> {
        let id = format!("{}/providers/{ASSIGNMENTS}/{name}", scope.trim_end_matches('/'));
        let key = id.to_ascii_lowercase();
        let subscription = self.engine.config().subscription_id.clone();
        let handle = self.engine.state::<AuthorizationState>();
        let not_found = || ArmError::not_found("RoleAssignmentNotFound", format!("The role assignment '{name}' is not found."));
        match self.method.as_str() {
            "GET" => {
                let state = handle.lock();
                let found = state.assignments.get(&key).ok_or_else(not_found)?;
                Ok(json_response(StatusCode::OK, &found.to_json(&subscription)))
            }
            "DELETE" => match handle.lock().assignments.remove(&key) {
                Some(removed) => Ok(json_response(StatusCode::OK, &removed.to_json(&subscription))),
                None => Ok(StatusCode::NO_CONTENT.into_response()),
            },
            "PUT" => self.put_assignment(scope, name, &id),
            _ => Err(self.unsupported(&[name.to_string()])),
        }
    }

    fn put_assignment(&self, scope: &str, name: &str, id: &str) -> Result<Response, ArmError> {
        // Unverified against Azure: the code for a name that is not a GUID.
        if !is_guid(name) {
            return Err(ArmError::bad_request(
                "InvalidRoleAssignmentId",
                format!("The role assignment ID '{name}' is not valid. The role assignment ID must be a GUID."),
            ));
        }
        let properties = self.body.get("properties").and_then(Value::as_object).ok_or_else(|| {
            ArmError::bad_request("InvalidRequestContent", "The request content was invalid and could not be deserialized: 'properties' is required.")
        })?;
        let text = |key: &str| properties.get(key).and_then(Value::as_str).filter(|s| !s.is_empty()).map(str::to_string);
        let role_definition_id = text("roleDefinitionId").ok_or_else(|| {
            ArmError::bad_request("InvalidRequestContent", "The request content was invalid and could not be deserialized: 'roleDefinitionId' is required.")
        })?;
        let principal_id = text("principalId").ok_or_else(|| {
            ArmError::bad_request("InvalidRequestContent", "The request content was invalid and could not be deserialized: 'principalId' is required.")
        })?;
        let role = role_guid(&role_definition_id).to_string();
        if !self.role_exists_for(&role, scope) {
            return Err(ArmError::bad_request(
                "RoleDefinitionDoesNotExist",
                format!("The specified role definition with ID '{role}' does not exist."),
            ));
        }
        if properties.get("condition").is_some_and(|c| !c.is_null())
            && properties.get("conditionVersion").and_then(Value::as_str) != Some("2.0")
        {
            return Err(ArmError::bad_request(
                "InvalidConditionVersion",
                "A role assignment with a condition must have conditionVersion '2.0'.",
            ));
        }
        let principal_type = text("principalType").or_else(|| self.known_identity(&principal_id).then(|| "ServicePrincipal".to_string()));
        let key = id.to_ascii_lowercase();
        let caller = self.principal.map(str::to_string);
        let subscription = self.engine.config().subscription_id.clone();
        let handle = self.engine.state::<AuthorizationState>();
        let mut state = handle.lock();
        let existing = state.assignments.get(&key).cloned();
        if let Some(existing) = &existing {
            if !existing.role.eq_ignore_ascii_case(&role) || !existing.principal_id.eq_ignore_ascii_case(&principal_id) {
                return Err(ArmError::conflict(
                    "RoleAssignmentUpdateNotPermitted",
                    "Tenant ID, application ID, principal ID, and scope are not allowed to be updated.",
                ));
            }
        } else if state.assignments.values().any(|a| {
            a.scope.eq_ignore_ascii_case(scope.trim_end_matches('/'))
                && a.role.eq_ignore_ascii_case(&role)
                && a.principal_id.eq_ignore_ascii_case(&principal_id)
        }) {
            return Err(ArmError::conflict("RoleAssignmentExists", "The role assignment already exists."));
        }
        let stamp = now();
        let member = |key: &str| properties.get(key).filter(|v| !v.is_null()).cloned();
        let assignment = Assignment {
            id: id.to_string(),
            name: name.to_string(),
            scope: scope.trim_end_matches('/').to_string(),
            role,
            principal_id,
            principal_type,
            description: member("description"),
            condition: member("condition"),
            condition_version: member("conditionVersion"),
            delegated_identity: member("delegatedManagedIdentityResourceId"),
            created_on: existing.as_ref().map(|e| e.created_on.clone()).unwrap_or_else(|| stamp.clone()),
            updated_on: stamp,
            created_by: existing.as_ref().map(|e| e.created_by.clone()).unwrap_or(caller),
        };
        let body = assignment.to_json(&subscription);
        state.assignments.insert(key, assignment);
        let status = if existing.is_some() { StatusCode::OK } else { StatusCode::CREATED };
        Ok(json_response(status, &body))
    }

    /// Whether `principal_id` is a managed identity the emulator issued.
    fn known_identity(&self, principal_id: &str) -> bool {
        let state = self.engine.state::<ArmState>();
        let state = state.lock();
        state.system_identity_clients.contains_key(principal_id)
            || state.resources().any(|r| {
                r.resource_type.eq_ignore_ascii_case("Microsoft.ManagedIdentity/userAssignedIdentities")
                    && r.properties.get("principalId").and_then(Value::as_str) == Some(principal_id)
            })
    }

    fn role_exists_for(&self, role: &str, scope: &str) -> bool {
        if builtin_roles().iter().any(|r| r["name"].as_str().is_some_and(|n| n.eq_ignore_ascii_case(role))) {
            return true;
        }
        let state = self.engine.state::<AuthorizationState>();
        let state = state.lock();
        state
            .custom
            .get(&role.to_ascii_lowercase())
            .is_some_and(|r| r.assignable_scopes.iter().any(|s| covers(s, scope)))
    }

    fn list_definitions(&self, scope: &str, filter: Option<&str>) -> Result<Response, ArmError> {
        let filter = parse_filter(filter)?;
        let prefix = definition_prefix(scope);
        let named = |role_name: &str| filter.role_name.as_deref().is_none_or(|n| n.eq_ignore_ascii_case(role_name));
        let typed = |kind: &str| filter.role_type.as_deref().is_none_or(|t| t.eq_ignore_ascii_case(kind));
        let mut items: Vec<Value> = Vec::new();
        if typed("BuiltInRole") {
            items.extend(
                builtin_roles()
                    .iter()
                    .filter(|r| named(r["roleName"].as_str().unwrap_or_default()))
                    .map(|r| builtin_json(r, &prefix)),
            );
        }
        if typed("CustomRole") {
            let state = self.engine.state::<AuthorizationState>();
            let state = state.lock();
            items.extend(
                state
                    .custom
                    .values()
                    .filter(|r| named(&r.role_name))
                    .filter(|r| r.assignable_scopes.iter().any(|s| covers(s, scope) || covers(scope, s)))
                    .map(|r| r.to_json(&prefix)),
            );
        }
        Ok(json_response(StatusCode::OK, &json!({"value": items})))
    }

    fn definition(&self, scope: &str, name: &str) -> Result<Response, ArmError> {
        let prefix = definition_prefix(scope);
        let key = name.to_ascii_lowercase();
        let builtin = builtin_roles().iter().find(|r| r["name"].as_str().is_some_and(|n| n.eq_ignore_ascii_case(name)));
        let handle = self.engine.state::<AuthorizationState>();
        let not_found = || {
            ArmError::not_found(
                "RoleDefinitionDoesNotExist",
                format!("The specified role definition with ID '{name}' does not exist."),
            )
        };
        match self.method.as_str() {
            "GET" => match builtin {
                Some(role) => Ok(json_response(StatusCode::OK, &builtin_json(role, &prefix))),
                None => {
                    let state = handle.lock();
                    let role = state.custom.get(&key).ok_or_else(not_found)?;
                    Ok(json_response(StatusCode::OK, &role.to_json(&prefix)))
                }
            },
            // Unverified against Azure: the code for changing a built-in role.
            "PUT" | "DELETE" if builtin.is_some() => Err(ArmError::new(
                StatusCode::FORBIDDEN,
                "BuiltInRoleCannotBeModified",
                format!("The built-in role '{name}' cannot be changed or deleted."),
            )),
            "DELETE" => {
                let mut state = handle.lock();
                if state.assignments.values().any(|a| a.role.eq_ignore_ascii_case(name)) {
                    return Err(ArmError::conflict(
                        "RoleDefinitionHasAssignments",
                        "There are existing role assignments referencing role. Delete all role assignments referencing this role before deleting the role definition.",
                    ));
                }
                match state.custom.remove(&key) {
                    Some(role) => Ok(json_response(StatusCode::OK, &role.to_json(&prefix))),
                    None => Ok(StatusCode::NO_CONTENT.into_response()),
                }
            }
            "PUT" => self.put_definition(scope, name, &prefix),
            _ => Err(self.unsupported(&[name.to_string()])),
        }
    }

    fn put_definition(&self, scope: &str, name: &str, prefix: &str) -> Result<Response, ArmError> {
        if !is_guid(name) {
            return Err(ArmError::bad_request(
                "InvalidRoleDefinitionId",
                format!("The role definition ID '{name}' is not valid. The role definition ID must be a GUID."),
            ));
        }
        let properties = self.body.get("properties").and_then(Value::as_object).ok_or_else(|| {
            ArmError::bad_request("InvalidRequestContent", "The request content was invalid and could not be deserialized: 'properties' is required.")
        })?;
        let role_name = properties
            .get("roleName")
            .and_then(Value::as_str)
            .filter(|s| !s.trim().is_empty())
            .ok_or_else(|| ArmError::bad_request("RoleDefinitionNameNullOrEmpty", "The role definition name cannot be null or empty."))?
            .to_string();
        let assignable_scopes: Vec<String> = properties
            .get("assignableScopes")
            .and_then(Value::as_array)
            .map(|scopes| scopes.iter().filter_map(Value::as_str).map(|s| s.trim_end_matches('/').to_string()).collect())
            .unwrap_or_default();
        if assignable_scopes.is_empty() {
            return Err(ArmError::bad_request(
                "MissingAssignableScopes",
                "The role definition must have at least one assignable scope.",
            ));
        }
        for assignable in &assignable_scopes {
            self.require_scope(assignable)?;
        }
        if !assignable_scopes.iter().any(|s| covers(scope, s) || covers(s, scope)) {
            return Err(ArmError::bad_request(
                "InvalidAssignableScopes",
                format!("The assignable scopes of a role definition created at '{scope}' must be at or under it."),
            ));
        }
        if builtin_roles().iter().any(|r| r["roleName"].as_str().is_some_and(|n| n.eq_ignore_ascii_case(&role_name))) {
            return Err(ArmError::conflict(
                "RoleDefinitionWithSameNameExists",
                format!("A role definition cannot be updated with a name that already exists: '{role_name}'."),
            ));
        }
        let key = name.to_ascii_lowercase();
        let handle = self.engine.state::<AuthorizationState>();
        let mut state = handle.lock();
        if state.custom.iter().any(|(k, r)| *k != key && r.role_name.eq_ignore_ascii_case(&role_name)) {
            return Err(ArmError::conflict(
                "RoleDefinitionWithSameNameExists",
                format!("A role definition cannot be updated with a name that already exists: '{role_name}'."),
            ));
        }
        let existing = state.custom.get(&key).cloned();
        let stamp = now();
        let role = CustomRole {
            name: name.to_string(),
            role_name,
            description: properties.get("description").cloned().unwrap_or(Value::Null),
            permissions: properties.get("permissions").cloned().unwrap_or_else(|| json!([])),
            assignable_scopes,
            created_on: existing.as_ref().map(|e| e.created_on.clone()).unwrap_or_else(|| stamp.clone()),
            updated_on: stamp,
            created_by: existing.as_ref().map(|e| e.created_by.clone()).unwrap_or(self.principal.map(str::to_string)),
        };
        let body = role.to_json(prefix);
        state.custom.insert(key, role);
        let status = if existing.is_some() { StatusCode::OK } else { StatusCode::CREATED };
        Ok(json_response(status, &body))
    }
}

fn invalid_scope(scope: &str) -> ArmError {
    ArmError::bad_request("InvalidScope", format!("The scope '{scope}' is not valid."))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn wildcards() {
        assert!(action_matches("*", "Microsoft.Storage/storageAccounts/write"));
        assert!(action_matches("Microsoft.Storage/*/read", "microsoft.storage/storageaccounts/read"));
        assert!(!action_matches("Microsoft.Storage/*/read", "Microsoft.Storage/storageAccounts/write"));
        assert!(action_matches("Microsoft.Authorization/*/Write", "Microsoft.Authorization/roleAssignments/write"));
        assert!(action_matches("*/read", "Microsoft.KeyVault/vaults/read"));
    }

    #[test]
    fn built_in_roles_load() {
        let owner = builtin_roles().iter().find(|r| r["roleName"] == "Owner").expect("Owner");
        assert_eq!(owner["name"], "8e3af657-a8ff-443c-a75c-2fe8c4bcb635");
        let contributor = builtin_roles().iter().find(|r| r["roleName"] == "Contributor").expect("Contributor");
        assert!(permits(&contributor["permissions"], "Microsoft.Storage/storageAccounts/write"));
        assert!(!permits(&contributor["permissions"], "Microsoft.Authorization/roleAssignments/write"));
    }

    #[test]
    fn permissions_from_paths() {
        let path = |p: &str| p.split('/').filter(|s| !s.is_empty()).map(String::from).collect::<Vec<_>>();
        let sub = "/subscriptions/s";
        assert_eq!(
            required_permission(&Method::PUT, &path("/subscriptions/s/resourceGroups/rg/providers/Microsoft.Storage/storageAccounts/a")),
            Some(("Microsoft.Storage/storageAccounts/write".into(), format!("{sub}/resourceGroups/rg/providers/Microsoft.Storage/storageAccounts/a")))
        );
        assert_eq!(
            required_permission(&Method::POST, &path("/subscriptions/s/resourceGroups/rg/providers/Microsoft.Storage/storageAccounts/a/listKeys")),
            Some(("Microsoft.Storage/storageAccounts/listKeys/action".into(), format!("{sub}/resourceGroups/rg/providers/Microsoft.Storage/storageAccounts/a")))
        );
        assert_eq!(
            required_permission(&Method::GET, &path("/subscriptions/s/resourceGroups/rg/providers/Microsoft.Storage/storageAccounts/a/blobServices/default/containers")),
            Some((
                "Microsoft.Storage/storageAccounts/blobServices/containers/read".into(),
                format!("{sub}/resourceGroups/rg/providers/Microsoft.Storage/storageAccounts/a/blobServices/default")
            ))
        );
        assert_eq!(
            required_permission(&Method::PUT, &path("/subscriptions/s/resourceGroups/rg/providers/Microsoft.Storage/storageAccounts/a/providers/Microsoft.Authorization/roleAssignments/g")),
            Some((
                "Microsoft.Authorization/roleAssignments/write".into(),
                format!("{sub}/resourceGroups/rg/providers/Microsoft.Storage/storageAccounts/a/providers/Microsoft.Authorization/roleAssignments/g")
            ))
        );
        assert_eq!(
            required_permission(&Method::DELETE, &path("/subscriptions/s/resourceGroups/rg")),
            Some(("Microsoft.Resources/subscriptions/resourceGroups/delete".into(), format!("{sub}/resourceGroups/rg")))
        );
        assert_eq!(required_permission(&Method::GET, &path("/subscriptions")), None);
    }
}
